function dateInput(value:string){if(/^\d{4}-\d{2}-\d{2}$/.test(value))return value;const match=value.match(/^(\d{1,2}) (January|February|March|April|May|June|July|August|September|October|November|December) (\d{4})$/i);if(!match)return '';const month=['january','february','march','april','may','june','july','august','september','october','november','december'].indexOf(match[2].toLowerCase())+1;return match[3]+'-'+String(month).padStart(2,'0')+'-'+match[1].padStart(2,'0')}
function roastDateLabel(value:string){const iso=dateInput(value);return iso?new Date(iso+'T12:00:00').toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):value||'Unknown'}
function roastWindow(roastDate:string){const iso=dateInput(roastDate);if(!iso)return {state:'unknown',label:'Roast date unknown'};const age=Math.floor((new Date(today()+'T12:00:00').valueOf()-new Date(iso+'T12:00:00').valueOf())/86400000);if(age<0)return {state:'unknown',label:'Roast date ahead'};if(age<7)return {state:'resting',label:`Resting · ${7-age}d to go`};if(age<=28)return {state:'optimal',label:`Optimal · ${29-age}d left`};return {state:'past',label:`Past peak · day ${age}`}}
